def _resolve_field(
    context: dict[str, Any],
    field_path: str,
) -> Any:
    """Resolve a dotted field path against a context dict of objects.

    Examples:
        _resolve_field(ctx, "classification.primary_category") -> enum value
        _resolve_field(ctx, "signature.latency_sensitivity.score") -> float
    """
    parts = field_path.split(".")
    obj = context[parts[0]]
    for part in parts[1:]:
        obj = getattr(obj, part)
    if isinstance(obj, Enum):
        return obj.value
    return obj


def _evaluate_operator(actual: Any, operator: RuleOperator, expected: Any) -> bool:
    """Evaluate a comparison operator between an actual value and expected value."""
    if operator == RuleOperator.EQ:
        return actual == expected
    if operator == RuleOperator.GT:
        return float(actual) > float(expected)
    if operator == RuleOperator.GTE:
        return float(actual) >= float(expected)
    if operator == RuleOperator.LT:
        return float(actual) < float(expected)
    if operator == RuleOperator.LTE:
        return float(actual) <= float(expected)
    if operator == RuleOperator.IN:
        if isinstance(expected, list):
            return actual in expected
        return actual in [expected]
    return False


def _render_template(
    template: str,
    context: dict[str, Any],
) -> str:
    """Render a rationale template by resolving {field.path} placeholders."""

    def replacer(match: re.Match[str]) -> str:
        path = match.group(1)
        try:
            value = _resolve_field(context, path)
            return str(value)
        except (KeyError, AttributeError, TypeError):
            return match.group(0)

    return re.sub(r"\{([^}]+)\}", replacer, template)


class StaticKnowledgeBase:
    """Phase 1 knowledge base backed by static YAML rules.

    Loads rules from a YAML file and evaluates them against workload
    classifications and signatures to produce rule matches.
    """

    def __init__(self) -> None:
        self._rules: dict[str, KnowledgeRule] = {}

    def load(self, rules_path: Path) -> None:
        """Load rules from a YAML file.

        Args:
            rules_path: Path to the YAML file containing rule definitions.
        """
        with open(rules_path) as f:
            raw_rules = yaml.safe_load(f)

        self._rules.clear()
        for raw in raw_rules:
            conditions = [
                RuleCondition(
                    field=c["field"],
                    operator=RuleOperator(c["operator"]),
                    value=c["value"],
                )
                for c in raw["conditions"]
            ]
            rule = KnowledgeRule(
                rule_id=raw["rule_id"],
                version=raw["version"],
                description=raw["description"],
                conditions=conditions,
                recommendations=raw["recommendations"],
                rationale_template=raw["rationale_template"],
            )
            self._rules[rule.rule_id] = rule

    def query(
        self,
        classification: WorkloadClassification,
        signature: WorkloadSignature,
    ) -> list[RuleMatch]:
        """Find all applicable rules and return matches with rendered rationale.

        Evaluates every loaded rule against the given classification and
        signature. A rule matches if ALL of its conditions are satisfied.

        Args:
            classification: The workload classification to match against.
            signature: The workload signature to match against.

        Returns:
            A list of RuleMatch objects for all matching rules.
        """
        context: dict[str, Any] = {
            "classification": classification,
            "signature": signature,
        }

        matches: list[RuleMatch] = []
        for rule in self._rules.values():
            matched_conditions: list[RuleCondition] = []
            all_matched = True

            for condition in rule.conditions:
