                    actual = _resolve_field(context, condition.field)
                    if _evaluate_operator(actual, condition.operator, condition.value):
                        matched_conditions.append(condition)
                    else:
                        all_matched = False
                        break
                except (KeyError, AttributeError, TypeError):
                    all_matched = False
                    break

            if all_matched and matched_conditions:
                # Build template context including rule_id
                template_context: dict[str, Any] = {
                    "classification": classification,
                    "signature": signature,
                    "rule_id": rule.rule_id,
                }
                rationale = _render_template(
                    rule.rationale_template, template_context
                )

                matches.append(
                    RuleMatch(
                        rule_id=rule.rule_id,
                        recommendations=rule.recommendations,
                        rationale=rationale.strip(),
                        matched_conditions=matched_conditions,
                    )
                )

        return matches

    def get_rule(self, rule_id: str) -> KnowledgeRule | None:
        """Retrieve a single rule by its ID.

        Args:
            rule_id: The stable identifier of the rule.

        Returns:
            The KnowledgeRule if found, otherwise None.
        """
        return self._rules.get(rule_id)
